class Solution {
  public int[][] insert(int[][] intervals, int[] newInterval) {
    List<int[]> res = new ArrayList<>();
    int i = 0;
    while (i < intervals.length && intervals[i][1] < newInterval[0]) {
      res.add(intervals[i++]);
    }
    int lo = newInterval[0], hi = newInterval[1];
    while (i < intervals.length && intervals[i][0] <= hi) {
      lo = Math.min(lo, intervals[i][0]);
      hi = Math.max(hi, intervals[i][1]);
      i++;
    }
    res.add(new int[] { lo, hi });
    while (i < intervals.length) {
      res.add(intervals[i++]);
    }
    return res.toArray(new int[res.size()][]);
  }
}

impl Solution {
  pub fn insert(intervals: Vec<Vec<i32>>, new_interval: Vec<i32>) -> Vec<Vec<i32>> {
    let mut res = vec![];
    let mut i = 0;
    while i < intervals.len() && intervals[i][1] < new_interval[0] {
      res.push(intervals[i].clone());
      i += 1;
    }
    let (mut lo, mut hi) = (new_interval[0], new_interval[1]);
    while i < intervals.len() && intervals[i][0] <= hi {
      lo = lo.min(intervals[i][0]);
      hi = hi.max(intervals[i][1]);
      i += 1;
    }
    res.push(vec![lo, hi]);
    while i < intervals.len() {
      res.push(intervals[i].clone());
      i += 1;
    }
    res
  }
}

